\left( {t_{n, k}}\right) p_{n,k},
\end{equation*}
by uniqueness of the coefficients of the basis functions, we must
have $f_{0} \left( {t_{n, k}}\right) = {\lambda }_{n, k}( f_0 )$
for all pairs $n,k$. But then $1 = \int_a^b f_0 d \mu_{n,k}$ by (\ref{mu}), so
admissible measures $\mu_{n,k}$ must be such that
$d P_{n,k}:= f_0 d \mu_{n,k}$ defines a probability $P_{n,k}$. With
this notation, the second condition $L_n (f_1) = f_1$ leads to
\begin{equation*}
{\lambda }_{n, k}( f_1 )  = f_{0}
\left( {t_{n, k}}\right) \int_a^b \frac{f_1}{f_0} d P_{n,k},
\end{equation*}
so again by uniqueness of the coefficients of the basis functions, we
have
\begin{equation*}
f_{0}
\left( {t_{n, k}}\right) \int_a^b \frac{f_1}{f_0} d P_{n,k}
=
{\lambda }_{n, k}( f_1 )  = f_{1}
\left( {t_{n, k}}\right) =  f_{0}
\left( {t_{n, k}}\right) \frac{f_{1}
\left( {t_{n, k}}\right)}{f_{0}
\left( {t_{n, k}}\right)}.
\end{equation*}
Thus,
\begin{equation}\label{aver}
\frac{f_{1}
\left( {t_{n, k}}\right)}{f_{0}
\left( {t_{n, k}}\right)}
= \int_a^b \frac{f_1}{f_0} d P_{n,k}
\end{equation}
for all pairs $n,k$.


